<script>
(async function() {
    const $ = id => document.getElementById(id);
    const $$ = sel => document.querySelectorAll(sel);

    // --- Base64 图片库 ---
    // 请在此处替换为您转换好的Base64字符串，或使用网络图片链接
    const CharImages = {
        '苏瑶': [
            'https://cdn.jsdelivr.net/gh/zzdzzdxx/ST-@main/分享图床/苏瑶/苏瑶咬唇.jpg', // 占位图1
            'https://cdn.jsdelivr.net/gh/zzdzzdxx/ST-@main/分享图床/苏瑶/吐舌.jpg', // 占位图2
        ],
        '苏双双': [
            'https://cdn.jsdelivr.net/gh/zzdzzdxx/ST-@main/分享图床/苏双双/绿丝绸苏双双.jpg'
        ],
        '叶婉秋': [
            'https://cdn.jsdelivr.net/gh/zzdzzdxx/ST-@main/分享图床/叶婉秋/叶婉秋红色丝衣.jpg'
        ]
    };

    // 敏感度阶梯定义
    const SENSE_LEVELS = ['青涩', '觉醒', '渴求', '失控', '享乐', '纵情', '畅爽', '绝巅', '爽泄', '登仙', '纵欲', '欢愉'];

    // 状态管理
    const AppState = {
        activeChar: '苏瑶',
        mvuData: null,
        isReady: false,
        theme: 'light'
    };

    // --- 工具函数 ---
    const getLoveTitle = (lv) => {
        if (lv < 1) return '友善';
        if (lv < 10) return '暗恋';
        if (lv < 20) return '初恋';
        if (lv < 30) return '热恋';
        if (lv < 40) return '眷恋';
        if (lv < 50) return '依恋';
        if (lv < 60) return '深爱';
        if (lv < 70) return '病娇';
        if (lv < 80) return '生死相依';
        if (lv < 90) return '灵魂伴侣';
        if (lv < 100) return '永恒契约';
        if (lv < 110) return '终极归宿';
        return '真爱化身';
    };

    const bindEditableTexts = (container) => {
        container.querySelectorAll('.editable-text').forEach(el => {
            if(el.dataset.bound) return;
            el.dataset.bound = "true";
            el.addEventListener('click', e => { e.preventDefault(); e.stopPropagation(); });
            el.addEventListener('dblclick', function(e) {
                e.preventDefault();
                e.stopPropagation();
                if(this.querySelector('input')) return;
                const currentVal = this.textContent;
                const path = this.getAttribute('data-path');
                const inputVal = (currentVal === '\xa0' || currentVal.trim() === '') ? '' : currentVal;
                this.innerHTML = `<input type="text" class="edit-input" value="${inputVal}">`;
                const input = this.querySelector('input');
                input.focus();

                input.addEventListener('click', ev => ev.stopPropagation());
                input.addEventListener('dblclick', ev => ev.stopPropagation());

                const save = () => {
                    const newVal = input.value.trim() || '无';
                    this.innerHTML = formatEmptyVal(newVal);
                    const oldVal = (currentVal === '\xa0' || currentVal.trim() === '') ? '无' : currentVal;
                    if(newVal !== oldVal) {
                        updateMvu(path, newVal, "已更新");
                    }
                };
                input.addEventListener('blur', save);
                input.addEventListener('keydown', (ev) => { if(ev.key === 'Enter') input.blur(); });
            });
        });
    };
    // 格式化空值
    const formatEmptyVal = (val) => {
        if (!val || val === '无' || val === '未觉醒' || val === '未知') {
            return `<span class="text-neon-red">&nbsp;</span>`;
        }
        return val;
    };

    // 爱意喷泉特效
    const createHeartFountain = (element) => {
        const fountain = document.createElement('div');
        fountain.className = 'heart-fountain';
        if (window.getComputedStyle(element).position === 'static') {
            element.style.position = 'relative';
        }
        element.appendChild(fountain);

        const duration = 6000;
        const interval = 100;
        let elapsed = 0;

        const timer = setInterval(() => {
            if (elapsed >= duration) {
                clearInterval(timer);
                setTimeout(() => fountain.remove(), 2000);
                return;
            }
            const count = Math.floor(Math.random() * 3) + 2;
            for (let i = 0; i < count; i++) {
                const particle = document.createElement('i');
                particle.className = 'fas fa-heart heart-particle';
                const angle = (Math.random() * 60 - 30) * (Math.PI / 180);
                const velocity = Math.random() * 60 + 40;
                const tx = Math.sin(angle) * velocity + 'px';
                const ty = -Math.cos(angle) * velocity - (Math.random() * 30) + 'px';
                const rot = (Math.random() * 360) + 'deg';

                particle.style.setProperty('--tx', tx);
                particle.style.setProperty('--ty', ty);
                particle.style.setProperty('--rot', rot);
                particle.style.fontSize = (Math.random() * 10 + 10) + 'px';
                if (Math.random() > 0.5) particle.style.color = '#ff4d6d';

                fountain.appendChild(particle);
                particle.addEventListener('animationend', () => particle.remove());
            }
            elapsed += interval;
        }, interval);
    };

    // 飘字特效
    const showFloatingNumber = (element, text, type = 'pos') => {
        const floater = document.createElement('span');
        floater.textContent = text;
        floater.className = `floating-number float-${type}`;
        const offsetX = (Math.random() - 0.5) * 20;
        floater.style.left = `calc(50% + ${offsetX}px)`;
        floater.style.top = '0';
        if (window.getComputedStyle(element).position === 'static') {
            element.style.position = 'relative';
        }
        element.appendChild(floater);
        floater.addEventListener('animationend', () => floater.remove());
    };

    const showToast = (msg, type='info') => {
        if(typeof triggerSlash === 'function') {
            const safeMsg = typeof msg === 'string' ? msg.replace(/(\\+)?([|{}])/g, (m, s, c) => (s || '') + (s || '') + '\\' + c) : msg;
            triggerSlash(`/echo severity=${type} ${safeMsg}`);
        } else {
            console.log(`[${type}] ${msg}`);
        }
    };

    const createParticles = () => {
        const container = $('particles-container');
        if(!container) return;
        container.innerHTML = '';
        for(let i=0; i<15; i++) {
            const p = document.createElement('div');
            p.className = 'particle';
            const size = Math.random() * 6 + 2;
            p.style.width = `${size}px`;
            p.style.height = `${size}px`;
            p.style.left = `${Math.random() * 100}%`;
            p.style.animationDuration = `${Math.random() * 3 + 2}s`;
            p.style.animationDelay = `${Math.random() * 2}s`;
            container.appendChild(p);
        }
    };

    // --- 数据交互逻辑 ---
    const fetchMvuData = () => {
        if (typeof getAllVariables !== 'function' || typeof _ === 'undefined') return false;
        AppState.mvuData = getAllVariables();
        return !!AppState.mvuData;
    };

    const updateMvu = async (path, newValue, successMsg) => {
        if (typeof Mvu === 'undefined' || typeof getCurrentMessageId !== 'function') {
            showToast("MVU环境未就绪", "error");
            return false;
        }
        try {
            const msgId = getCurrentMessageId();
            const data = Mvu.getMvuData({ type: 'message', message_id: msgId });
            if (!data) return false;

            _.set(data, path, newValue);
            await Mvu.replaceMvuData(data, { type: 'message', message_id: msgId });

            if(successMsg) showToast(successMsg, "success");
            fetchMvuData();
            renderUI();
            return true;
        } catch (e) {
            console.error(e);
            showToast("数据更新失败", "error");
            return false;
        }
    };

    // --- 渲染逻辑 ---

    // 渲染图片区
    const renderImage = (charData) => {
        const imgEl = $('c-image');
        const images = CharImages[AppState.activeChar] || [];
        if (images.length === 0) {
            imgEl.src = '';
            return;
        }
        // 读取MVU中的图片索引，若无则默认为0
        let imgIdx = _.get(charData, '装备与心理.当前图片索引', 0);
        if (imgIdx >= images.length) imgIdx = 0;
        imgEl.src = images[imgIdx];
    };

    const renderGlobal = () => {
        const d = AppState.mvuData;
        const t = _.get(d, 'stat_data.全局.时间', {});

        const year  = t.年  ?? '--';
        const month = t.月  ? String(t.月).padStart(2, '0') : '--';
        const day   = t.日  ? String(t.日).padStart(2, '0') : '--';
        const hour  = t.时  ? String(t.时).padStart(2, '0') : '--';
        const min   = t.分  ? String(t.分).padStart(2, '0') : '--';
        const week  = t.星期 ?? '';

        $('g-datetime').textContent = `${year}年${month}月${day}日 ${hour}:${min} ${week}`;
        $('g-loc').textContent = _.get(d, 'stat_data.全局.地点', '未知');
        $('g-cash').textContent = _.get(d, 'stat_data.全局.资源.现金', 0);
        $('g-score').textContent = _.get(d, 'stat_data.全局.资源.积分', 0);
    };

    const renderCore = (charData) => {
        const love = charData.好感与爱意 || {};
        const sense = charData.敏感度与境界 || {};
        const multi = charData.多维行为检测 || {};

        const nickMap = { '苏瑶': '瑶瑶', '苏双双': '双双', '叶婉秋': '婉秋' };
        $('c-nickname').textContent = nickMap[AppState.activeChar] || AppState.activeChar;

        // 强制前端计算称号，确保显示正确
        const currentLoveLv = love.爱意等级 || 0;
        $('c-love-title').textContent = getLoveTitle(currentLoveLv);
        $('c-love-lv').textContent = currentLoveLv;
        $('c-love-val').textContent = love.爱意值 || 0;

        // 计算体味旋律评价
        const melody = charData.体味旋律 || {};
        let rank = 'SS';
        const hasTempBody = melody.临时体香 && melody.临时体香 !== '无' && melody.临时体香 !== '未觉醒' && melody.临时体香 !== '未开发' && melody.临时体香 !== '未知';
        const hasTempTaste = melody.临时口感 && melody.临时口感 !== '无' && melody.临时口感 !== '未觉醒' && melody.临时口感 !== '未开发' && melody.临时口感 !== '未知';
        if (hasTempTaste) {
            rank = 'SSS+';
        } else if (hasTempBody) {
            rank = 'SSS';
        }
        const rankEl = $('c-melody-rank');
        if (rankEl) {
            rankEl.textContent = rank;
            // 清理旧特效
            rankEl.classList.remove('rank-sss', 'rank-sss-plus');
            // 应用新特效
            if (rank === 'SSS') {
                rankEl.classList.add('rank-sss');
            } else if (rank === 'SSS+') {
                rankEl.classList.add('rank-sss-plus');
            }
        }

        // 进度条逻辑：基于累计值计算，满值为2000
        const totalLove = love.累计爱意值 || love.爱意值 || 0;
        const lovePct = Math.min(100, (totalLove / 2000) * 100);
        $('c-love-bar').style.width = `${lovePct}%`;
        const loveTotalEl = $('c-love-total');
        if (loveTotalEl) loveTotalEl.textContent = totalLove;

        $('c-favor-val').textContent = love.好感度 || 0;

        // 进度条逻辑：基于累计值计算，满值为2000
        const totalFavor = love.累计好感度 || love.好感度 || 0;
        const favorPct = Math.min(100, (totalFavor / 2000) * 100);
        $('c-favor-bar').style.width = `${favorPct}%`;
        const favorTotalEl = $('c-favor-total');
        if (favorTotalEl) favorTotalEl.textContent = totalFavor;

        $('c-sense-val').textContent = sense.当前敏感度等级 || '青涩';
        $('c-res-val').textContent = sense._生理抗性 || 100;
        $('c-res-bar').style.width = `${sense._生理抗性 || 100}%`;
        $('c-climax-val').textContent = sense.圆融计数 || 0;

        const currentRealm = sense.红鸾境界 || '锁灵';
        $('c-realm-val').textContent = currentRealm;
        $('c-star-val').textContent = multi.乳星 || 0;
        $('c-preg-val').textContent = multi.孕灵状态 || '无';
        $('c-birth-val').textContent = multi.诞灵次数 || 0;
        $('c-reso-val').textContent = multi.共鸣次数 || 0;
        $('c-over-val').textContent = multi.感官过载次数 || 0;

        // 动态计算境界突破提示
        const globalScore = _.get(AppState.mvuData, 'stat_data.全局.资源.积分', 0);
        const curClimax = sense.圆融计数 || 0;
        const curStar = multi.乳星 || 0;
        const curBirth = multi.诞灵次数 || 0;
        const curReso = multi.共鸣次数 || 0;
        const curOver = multi.感官过载次数 || 0;
        const curLoveLv = love.爱意等级 || 0;

        let tooltipText = '';
        let targetRealm = currentRealm;
        if (curClimax >= 100 && curStar >= 200 && curOver >= 20 && curLoveLv >= 80) targetRealm = '众妙'; 
        else if (curClimax >= 50 && curStar >= 100 && curReso >= 10) targetRealm = '灵融';
        else if (curClimax >= 20 && curStar >= 20 && curBirth >= 1 && curLoveLv >= 20) targetRealm = '蕴灵';
        else if (curClimax >= 5 && curStar >= 1) targetRealm = '星衍';
        else if (curClimax >= 2) targetRealm = '玉润';

        const realms = ['锁灵', '玉润', '星衍', '蕴灵', '灵融', '众妙'];
        const canBreakthrough = realms.indexOf(targetRealm) > realms.indexOf(currentRealm);

        if (currentRealm === '锁灵') {
            tooltipText = `【突破至 玉润】\n圆融计数: ${curClimax}/5\n积分: ${globalScore}/221`;
        } else if (currentRealm === '玉润') {
            tooltipText = `【突破至 星衍】\n圆融计数: ${curClimax}/10\n积分: ${globalScore}/401`;
        } else if (currentRealm === '星衍') {
            tooltipText = `【突破至 蕴灵】\n圆融计数: ${curClimax}/40\n乳星: ${curStar}/30\n诞灵次数: ${curBirth}/1\n爱意等级: ${curLoveLv}/30`;
        } else if (currentRealm === '蕴灵') {
            tooltipText = `【突破至 灵融】\n圆融计数: ${curClimax}/60\n共鸣次数: ${curReso}/10`;
        } else if (currentRealm === '灵融') {
            tooltipText = `【突破至 众妙】\n圆融计数: ${curClimax}/80\n感官过载: ${curOver}/1\n爱意等级: ${curLoveLv}/80`;
        } else if (currentRealm === '众妙') {
            tooltipText = `已达最高境界【众妙】\n万法自然，灵枢圆融。`;
        }

        const realmValEl = $('c-realm-val');
        if (canBreakthrough) {
            realmValEl.classList.add('text-gold-flash');
            realmValEl.style.cursor = 'pointer';
            realmValEl.onclick = () => {
                if(typeof triggerSlash === 'function') {
                    triggerSlash(`/setinput 协助她突破到${targetRealm}境界`);
                }
            };
            tooltipText = `【可突破至 ${targetRealm}】\n点击协助突破！\n\n` + tooltipText;
        } else {
            realmValEl.classList.remove('text-gold-flash');
            realmValEl.style.cursor = 'default';
            realmValEl.onclick = null;
        }

        const realmTooltip = $('c-realm-tooltip');
        if (realmTooltip) realmTooltip.textContent = tooltipText;

        $('c-thought-val').textContent = charData.装备与心理?.实时内心 || '...';

        // 动态背景色偏移
        const levelIdx = SENSE_LEVELS.indexOf(sense.当前敏感度等级 || '青涩');
        const ratio = Math.max(0, Math.min(1, levelIdx / (SENSE_LEVELS.length - 1)));

        const wrapper = $('monitor-app');
        if (AppState.theme === 'dark') {
            const r1 = 26 + (34 * ratio), g1 = 5 + (5 * ratio), b1 = 10 + (10 * ratio);
            const r2 = 40 + (40 * ratio), g2 = 10 + (10 * ratio), b2 = 20 + (10 * ratio);
            wrapper.style.setProperty('--dynamic-bg-1', `rgba(${r1},${g1},${b1},0.9)`);
            wrapper.style.setProperty('--dynamic-bg-2', `rgba(${r2},${g2},${b2},0.8)`);
        } else {
            const r1 = 255, g1 = 240 - (40 * ratio), b1 = 245 - (35 * ratio);
            const r2 = 248 + (7 * ratio), g2 = 195 - (95 * ratio), b2 = 205 - (105 * ratio);
            wrapper.style.setProperty('--dynamic-bg-1', `rgba(${r1},${g1},${b1},0.85)`);
            wrapper.style.setProperty('--dynamic-bg-2', `rgba(${r2},${g2},${b2},0.6)`);
        }
    };

    const renderFluids = (charData) => {
        const fluids = charData.体液状态 || {};
        const melody = charData.体味旋律 || {};
        const container = $('c-fluids-container');

        const bodyEl = $('c-melody-body');
        const fluidEl = $('c-melody-fluid');
        const tasteEl = $('c-melody-taste');
        const tempBodyEl = $('c-melody-temp-body');
        const tempTasteEl = $('c-melody-temp-taste');

        if(bodyEl) {
            bodyEl.innerHTML = formatEmptyVal(melody.体香);
            bodyEl.setAttribute('data-path', `stat_data.角色.${AppState.activeChar}.体味旋律.体香`);
        }
        if(fluidEl) {
            fluidEl.innerHTML = formatEmptyVal(melody.体液香);
            fluidEl.setAttribute('data-path', `stat_data.角色.${AppState.activeChar}.体味旋律.体液香`);
        }
        if(tasteEl) {
            tasteEl.innerHTML = formatEmptyVal(melody.口感);
            tasteEl.setAttribute('data-path', `stat_data.角色.${AppState.activeChar}.体味旋律.口感`);
        }

        // 临时体香和临时口感处理
        // 判断当前面板是否处于双击嵌入展开状态
        const isEmbeddedOpen = container.style.display === 'grid' && !container.classList.contains('absolute-panel');

        if(tempBodyEl) {
            const tempBodyVal = melody.临时体香;
            const isEmpty = !tempBodyVal || tempBodyVal === '无' || tempBodyVal === '未觉醒' || tempBodyVal === '未开发' || tempBodyVal === '未知';

            if (isEmpty && !isEmbeddedOpen) {
                $('c-melody-temp-body-row').style.display = 'none';
            } else {
                $('c-melody-temp-body-row').style.display = 'flex';
                tempBodyEl.innerHTML = formatEmptyVal(tempBodyVal);
            }
            tempBodyEl.setAttribute('data-path', `stat_data.角色.${AppState.activeChar}.体味旋律.临时体香`);
        }

        if(tempTasteEl) {
            const tempTasteVal = melody.临时口感;
            const isEmpty = !tempTasteVal || tempTasteVal === '无' || tempTasteVal === '未觉醒' || tempTasteVal === '未开发' || tempTasteVal === '未知';

            if (isEmpty && !isEmbeddedOpen) {
                $('c-melody-temp-taste-row').style.display = 'none';
            } else {
                $('c-melody-temp-taste-row').style.display = 'flex';
                tempTasteEl.innerHTML = formatEmptyVal(tempTasteVal);
            }
            tempTasteEl.setAttribute('data-path', `stat_data.角色.${AppState.activeChar}.体味旋律.临时口感`);
        }

        const prefixMap = {
            '苏瑶': { 津液: '薄荷', 仙元: '薄荷', 灵泉: '薄荷茶芬', 兰露: '樱桃' },
            '苏双双': { 津液: '玉兰', 仙元: '荔枝', 灵泉: '普洱茶芬', 兰露: '玉兰' },
            '叶婉秋': { 津液: '玫瑰', 仙元: '玫瑰', 灵泉: '龙井茶芬', 兰露: '红酒' }
        };
        const pfx = prefixMap[AppState.activeChar] || { 津液: '', 仙元: '', 灵泉: '', 兰露: '' };

        let html = '';
        const addTag = (lbl, val) => {
            html += `<div class="data-tag" style="flex-direction: row; justify-content: space-between; align-items: center; padding: 4px 8px;"><span class="lbl" style="margin-bottom: 0;">${lbl}</span><span class="val val-pink-bold">${formatEmptyVal(val)}</span></div>`;
        };

        addTag(`${pfx.津液}津液`, fluids.津液);
        addTag('腋下清汗', fluids.腋下清汗);
        addTag('足汗油膏', fluids.足汗油膏);
        addTag(`醇湿仙元`, fluids.醇湿仙元);
        addTag(`骚香灵泉`, fluids.骚香灵泉);
        addTag(`兰露肠液`, fluids.兰露肠液);

        container.innerHTML = html;
    };

    const renderEvo = (charData) => {
        const evo = charData.部位进化 || {};
        const container = $('c-evo-container');
        let html = '';

        const getDisplayLevel = (val) => {
            if (val >= 100) return 'MAX';
            if (val >= 81) return 'Lv5';
            if (val >= 41) return 'Lv4';
            if (val >= 16) return 'Lv3';
            if (val >= 11) return 'Lv2';
            if (val >= 6) return 'Lv1';
            return 'Lv0';
        };

        const parts = ['香舌', '奶子', '小穴', '菊蕊'];
        parts.forEach(p => {
            const d = evo[p] || { 数值:0, _Lv:0, 状态:'未开发', 强化部位1:'无', 强化部位2:'无' };
            const isMax = d.数值 >= 100;
            const pct = isMax ? '100%' : (d.数值 % 100) + '%';
            const maxClass = isMax ? 'is-max' : '';
            const dropId = `drop-${p}`;
            const displayLevel = getDisplayLevel(d.数值);
            const levelStyle = isMax ? 'font-size: var(--fs-xs); color: var(--c-accent); text-shadow: 0 0 5px var(--c-accent);' : 'font-size: var(--fs-xs);';

            let displayName = p;
            if (p === '奶子') {
                const isNaiZi = localStorage.getItem('mvu_monitor_name_奶子') === 'true';
                displayName = isNaiZi ? '奶子' : '双峦';
            } else if (p === '小穴') {
                const isXiaoXue = localStorage.getItem('mvu_monitor_name_小穴') === 'true';
                displayName = isXiaoXue ? '小穴' : '仙脉';
            }

            const formatEnhanceVal = (val) => {
                if (!val || val === '无' || val === '未觉醒') return `<span class="text-neon-red">&nbsp;</span>`;
                return val;
            };

            html += `
                <div class="evo-container-item" id="evo-item-${p}">
                    <div class="evo-flipper">
                        <!-- 正面 -->
                        <div class="evo-front">
                            <div class="evo-top-row">
                                <div class="ring-wrapper ${maxClass}" style="--pct: ${pct}; cursor: pointer;" onclick="document.getElementById('evo-item-${p}').classList.toggle('flipped'); event.stopPropagation();" title="点击翻转查看强化">
                                    <div class="ring-inner" style="${levelStyle}">${displayLevel}</div>
                                </div>
                                <div class="evo-name-row"><span class="evo-part-name" data-part="${p}" style="cursor:pointer;" title="双击切换名称">${displayName}</span> <span class="text-bright-pink">${d.数值}</span></div>
                            </div>
                            <div class="fancy-divider"><span>·</span></div>
                            <div class="evo-desc editable-text" data-path="stat_data.角色.${AppState.activeChar}.部位进化.${p}.状态" title="${d.状态}">${formatEmptyVal(d.状态)}</div>
                        </div>
                        <!-- 背面 -->
                        <div class="evo-back" onclick="document.getElementById('evo-item-${p}').classList.toggle('flipped'); event.stopPropagation();" title="点击翻转回正面" style="cursor: pointer;">
                            <div class="fancy-divider fancy-divider-gold" style="margin: 0 0 2px 0; font-size: var(--fs-xs);"><span>强化</span></div>
                            <div class="evo-enhance-item item-bubble" style="justify-content: center;"><span class="editable-text text-gold-flash" data-path="stat_data.角色.${AppState.activeChar}.部位进化.${p}.强化部位1" style="min-height: 1.2em; display: inline-block; overflow: hidden; text-overflow: ellipsis; text-align: center;">${formatEnhanceVal(d.强化部位1)}</span></div>
                            <div class="evo-enhance-item item-bubble" style="justify-content: center;"><span class="editable-text text-gold-flash" data-path="stat_data.角色.${AppState.activeChar}.部位进化.${p}.强化部位2" style="min-height: 1.2em; display: inline-block; overflow: hidden; text-overflow: ellipsis; text-align: center;">${formatEnhanceVal(d.强化部位2)}</span></div>
                        </div>
                    </div>
                </div>
            `;
        });
        container.innerHTML = html;
        bindEditableTexts(container);

        // 绑定双击切换名称事件
        container.querySelectorAll('.evo-part-name').forEach(el => {
            el.addEventListener('dblclick', (e) => {
                e.stopPropagation();
                const part = e.currentTarget.getAttribute('data-part');
                if (part === '奶子' || part === '小穴') {
                    const key = `mvu_monitor_name_${part}`;
                    const current = localStorage.getItem(key) === 'true';
                    localStorage.setItem(key, !current);
                    renderUI();
                }
            });
        });
    };

    const renderEditableBlocks = (charData) => {
        const eq = charData.装备与心理 || {};

        // 装备 (3x2)
        const eqCont = $('c-equip-container');
        let eqHtml = '';
        ['上身', '下身', '内衣', '内裤', '美腿', '玉足'].forEach(k => {
            const val = eq[k];
            eqHtml += `<div class="data-tag item-bubble" style="flex-direction: row; justify-content: flex-start; align-items: center; gap: 4px;"><span class="lbl" style="margin-bottom: 0; min-width: 3em; text-align: left;">${k}</span><span class="val editable-text val-pink-bold" data-path="stat_data.角色.${AppState.activeChar}.装备与心理.${k}" style="min-height: 1.2em; text-align: left;">${formatEmptyVal(val)}</span></div>`;
        });
        eqCont.innerHTML = eqHtml;

        // 配饰 (2x4)
        const accCont = $('c-acc-container');
        let accHtml = '';
        const rawAcc = eq.配饰 || [];
        for(let i=0; i<8; i++) {
            const val = rawAcc[i];
            accHtml += `<div class="data-tag item-bubble" style="justify-content: center;"><span class="val editable-text val-pink-bold" data-path="stat_data.角色.${AppState.activeChar}.装备与心理.配饰[${i}]" style="min-height: 1.2em;">${formatEmptyVal(val)}</span></div>`;
        }
        accCont.innerHTML = accHtml;

        // 性癖 (2x3)
        const fetCont = $('c-fetish-container');
        let fetHtml = '';
        const rawFet = eq.性癖档案 || [];
        for(let i=0; i<6; i++) {
            const val = rawFet[i];
            fetHtml += `<div class="data-tag item-bubble" style="justify-content: center;"><span class="val editable-text val-pink-bold" data-path="stat_data.角色.${AppState.activeChar}.装备与心理.性癖档案[${i}]" style="min-height: 1.2em;">${formatEmptyVal(val)}</span></div>`;
        }
        fetCont.innerHTML = fetHtml;

        // 绑定双击编辑事件
        $$('.editable-text').forEach(el => {
            el.addEventListener('click', e => { e.preventDefault(); e.stopPropagation(); });
            el.addEventListener('dblclick', function(e) {
                e.preventDefault();
                e.stopPropagation();
                if(this.querySelector('input')) return;
                const currentVal = this.textContent;
                const path = this.getAttribute('data-path');
                const inputVal = (currentVal === '\xa0' || currentVal.trim() === '') ? '' : currentVal;
                this.innerHTML = `<input type="text" class="edit-input" value="${inputVal}">`;
                const input = this.querySelector('input');
                input.focus();

                // 阻止输入框内部点击冒泡
                input.addEventListener('click', ev => ev.stopPropagation());
                input.addEventListener('dblclick', ev => ev.stopPropagation());

                const save = () => {
                    const newVal = input.value.trim() || '无';
                    this.innerHTML = formatEmptyVal(newVal);
                    const oldVal = (currentVal === '\xa0' || currentVal.trim() === '') ? '无' : currentVal;
                    if(newVal !== oldVal) {
                        updateMvu(path, newVal, "已更新");
                    }
                };
                input.addEventListener('blur', save);
                input.addEventListener('keydown', (ev) => { if(ev.key === 'Enter') input.blur(); });
            });
        });
    };

    const renderUI = () => {
        if (!AppState.isReady || !AppState.mvuData) return;

        renderGlobal();

        const charData = _.get(AppState.mvuData, `stat_data.角色.${AppState.activeChar}`, {});
        renderImage(charData);
        renderCore(charData);
        renderEvo(charData);
        renderFluids(charData);
        renderEditableBlocks(charData);
    };

    // --- 交互绑定 ---
    const bindEvents = () => {
        // 全局点击关闭下拉菜单、Tooltip 和悬浮面板
        document.addEventListener('click', (e) => {
            if (!e.target.closest('.evo-container-item')) {
                const flippedItems = $('c-evo-container')?.querySelectorAll('.evo-container-item.flipped');
                if (flippedItems) {
                    flippedItems.forEach(el => el.classList.remove('flipped'));
                }
            }
            if (!e.target.closest('.tooltip')) {
                $$('.tooltip.active-click').forEach(el => el.classList.remove('active-click'));
            }
            // 点击空白处关闭悬浮的体液面板
            if (!e.target.closest('#melody-wrapper-div') && !e.target.closest('#c-fluids-container')) {
                const fluidsContainer = $('c-fluids-container');
                if (fluidsContainer && fluidsContainer.classList.contains('absolute-panel')) {
                    fluidsContainer.style.display = 'none';
                }
            }
        });

        // Tooltip 单击开关 (常驻/取消)
        $$('.tooltip').forEach(el => {
            el.addEventListener('click', (e) => {
                // 如果点击的是内部的可编辑文本、输入框或进度条本身，不触发 tooltip 切换
                if (e.target.closest('.editable-text') || e.target.tagName === 'INPUT' || e.target.closest('.progress-track')) return;

                const isActive = el.classList.contains('active-click');
                // 关闭其他
                $$('.tooltip.active-click').forEach(t => {
                    if (t !== el) t.classList.remove('active-click');
                });
                if (!isActive) {
                    el.classList.add('active-click');
                } else {
                    el.classList.remove('active-click');
                }
            });
        });

        // 图片点击切图
        $('c-image-zone').addEventListener('click', () => {
            const images = CharImages[AppState.activeChar] || [];
            if (images.length <= 1) return;

            const charData = _.get(AppState.mvuData, `stat_data.角色.${AppState.activeChar}`, {});
            let imgIdx = _.get(charData, '装备与心理.当前图片索引', 0);
            imgIdx = (imgIdx + 1) >= images.length ? 0 : imgIdx + 1;

            const path = `stat_data.角色.${AppState.activeChar}.装备与心理.当前图片索引`;
            updateMvu(path, imgIdx); // 更新MVU并触发重绘
        });

        // 主题切换
        $('toggle-theme').addEventListener('click', () => {
            const wrapper = $('monitor-app');
            const icon = $('toggle-theme').querySelector('i');
            if (AppState.theme === 'light') {
                AppState.theme = 'dark';
                wrapper.classList.add('theme-dark');
                icon.className = 'fas fa-sun';
            } else {
                AppState.theme = 'light';
                wrapper.classList.remove('theme-dark');
                icon.className = 'fas fa-moon';
            }
            localStorage.setItem('mvu_monitor_theme', AppState.theme);
            renderUI();
        });

        // 最小化切换 (按钮点击)
        $('toggle-min').addEventListener('click', (e) => {
            e.stopPropagation();
            const app = $('monitor-app');
            app.classList.toggle('minimized');
            const isMin = app.classList.contains('minimized');
            localStorage.setItem('mvu_monitor_minimized', isMin);
            const icon = $('toggle-min').querySelector('i');
            icon.className = isMin ? 'fas fa-expand-arrows-alt' : 'fas fa-compress-alt';
        });

        // 最小化状态下点击整行展开
        document.querySelector('.global-bar').addEventListener('click', (e) => {
            const app = $('monitor-app');
            if (app.classList.contains('minimized')) {
                // 如果点击的是主题切换按钮，不在这里处理展开，让主题切换自己处理
                if (e.target.closest('#toggle-theme')) return;

                app.classList.remove('minimized');
                localStorage.setItem('mvu_monitor_minimized', false);
                const icon = $('toggle-min').querySelector('i');
                if(icon) icon.className = 'fas fa-compress-alt';
            }
        });

        // 装备栏折叠状态持久化
        const equipDetails = $('c-equip-details');
        if (equipDetails) {
            equipDetails.addEventListener('toggle', () => {
                localStorage.setItem('mvu_monitor_equip_open', equipDetails.open);
            });
        }

        // 配饰栏折叠状态持久化
        const accDetails = $('c-acc-details');
        if (accDetails) {
            accDetails.addEventListener('toggle', () => {
                localStorage.setItem('mvu_monitor_acc_open', accDetails.open);
            });
        }

        // 性癖档案折叠状态持久化
        const fetishDetails = $('c-fetish-details');
        if (fetishDetails) {
            fetishDetails.addEventListener('toggle', () => {
                localStorage.setItem('mvu_monitor_fetish_open', fetishDetails.open);
            });
        }

        // Tab 切换
        $$('.tab-btn[data-char]').forEach(btn => {
            btn.addEventListener('click', (e) => {
                $$('.tab-btn').forEach(b => b.classList.remove('active'));
                e.currentTarget.classList.add('active');
                AppState.activeChar = e.currentTarget.getAttribute('data-char');
                renderUI();
            });
        });

        // 爱意值升级
        $('c-love-btn').addEventListener('click', async function() {
            const charData = _.get(AppState.mvuData, `stat_data.角色.${AppState.activeChar}`, {});
            const loveVal = _.get(charData, '好感与爱意.爱意值', 0);
            if (loveVal >= 100) {
                const pathBase = `stat_data.角色.${AppState.activeChar}.好感与爱意`;
                const currentLv = _.get(charData, '好感与爱意.爱意等级', 0);
                const nextLv = currentLv + 1;

                showFloatingNumber(this, '-100', 'neg');
                const lvNode = $('c-love-lv').parentNode;
                showFloatingNumber(lvNode, '+1 Lv', 'pos');
                createHeartFountain(lvNode);

                // 乐观更新本地数据
                _.set(AppState.mvuData, `${pathBase}.爱意值`, loveVal - 100);
                _.set(AppState.mvuData, `${pathBase}.爱意等级`, nextLv);
                _.set(AppState.mvuData, `${pathBase}._爱意阶段称号`, getLoveTitle(nextLv));
                renderUI();

                if (typeof Mvu !== 'undefined' && typeof getCurrentMessageId === 'function') {
                    const msgId = getCurrentMessageId();
                    const data = Mvu.getMvuData({ type: 'message', message_id: msgId });
                    if(data) {
                        _.set(data, `${pathBase}.爱意值`, loveVal - 100);
                        _.set(data, `${pathBase}.爱意等级`, nextLv);
                        _.set(data, `${pathBase}._爱意阶段称号`, getLoveTitle(nextLv));
                        await Mvu.replaceMvuData(data, { type: 'message', message_id: msgId });
                        showToast(`升级成功！爱意等级达到 Lv${nextLv}`, "success");
                        fetchMvuData();
                        renderUI(); // 确保写回后再次刷新UI
                    }
                }
            } else {
                showToast("爱意值不足100，无法升级", "warning");
            }
        });

        // 好感度转化
        $('c-favor-btn').addEventListener('click', async function() {
            const charData = _.get(AppState.mvuData, `stat_data.角色.${AppState.activeChar}`, {});
            const favor = _.get(charData, '好感与爱意.好感度', 0);
            if (favor >= 105) {
                const addLove = Math.floor(Math.random() * 7) + 4; // 4~10
                const pathBase = `stat_data.角色.${AppState.activeChar}.好感与爱意`;
                const currentLove = _.get(charData, '好感与爱意.爱意值', 0);
                const totalLove = _.get(charData, '好感与爱意.累计爱意值', currentLove);

                showFloatingNumber(this, '-5', 'neg');
                showFloatingNumber($('c-love-btn'), `+${addLove}`, 'pos');

                // 乐观更新本地数据
                _.set(AppState.mvuData, `${pathBase}.好感度`, favor - 5);
                _.set(AppState.mvuData, `${pathBase}.爱意值`, currentLove + addLove);
                _.set(AppState.mvuData, `${pathBase}.累计爱意值`, totalLove + addLove);
                renderUI();

                if (typeof Mvu !== 'undefined' && typeof getCurrentMessageId === 'function') {
                    const msgId = getCurrentMessageId();
                    const data = Mvu.getMvuData({ type: 'message', message_id: msgId });
                    if(data) {
                        _.set(data, `${pathBase}.好感度`, favor - 5);
                        _.set(data, `${pathBase}.爱意值`, currentLove + addLove);
                        _.set(data, `${pathBase}.累计爱意值`, totalLove + addLove);
                        await Mvu.replaceMvuData(data, { type: 'message', message_id: msgId });
                        showToast(`转化成功！爱意值 +${addLove}`, "success");
                        fetchMvuData();
                    }
                }
            } else {
                showToast("好感度不足105，无法转化", "warning");
            }
        });

        // 体味旋律面板交互 (悬停悬浮，双击嵌入，双击关闭)
        const melodySummary = $('melody-summary');
        const fluidsContainer = $('c-fluids-container');
        const melodyWrapper = $('melody-wrapper-div');

        // 阻止点击面板内部冒泡到 document 导致关闭
        fluidsContainer.addEventListener('click', (e) => e.stopPropagation());

        // 悬停展示：仅当鼠标进入小气泡范围内时触发展开
        melodySummary.addEventListener('mouseenter', (e) => {
            if (fluidsContainer.style.display !== 'grid' || fluidsContainer.classList.contains('absolute-panel')) {
                fluidsContainer.style.display = 'grid';
                fluidsContainer.classList.add('absolute-panel');
            }
        });

        // 移开隐藏：当鼠标离开气泡区域时，如果未进入展开面板，则隐藏
        melodySummary.addEventListener('mouseleave', (e) => {
            if (fluidsContainer.classList.contains('absolute-panel')) {
                if (!e.relatedTarget || !e.relatedTarget.closest('#c-fluids-container')) {
                    fluidsContainer.style.display = 'none';
                }
            }
        });

        // 移开隐藏：当鼠标离开展开面板时，如果未进入气泡区域，则隐藏
        fluidsContainer.addEventListener('mouseleave', (e) => {
            if (fluidsContainer.classList.contains('absolute-panel')) {
                if (!e.relatedTarget || !e.relatedTarget.closest('#melody-summary')) {
                    fluidsContainer.style.display = 'none';
                }
            }
        });

        // 双击嵌入/关闭 (绑定在外层，整行可双击)
        melodyWrapper.addEventListener('dblclick', (e) => {
            if (e.target.closest('.editable-text') || e.target.tagName === 'INPUT') return;

            if (fluidsContainer.style.display === 'grid' && !fluidsContainer.classList.contains('absolute-panel')) {
                // 当前是嵌入展开状态，双击关闭
                fluidsContainer.style.display = 'none';
                localStorage.setItem('mvu_monitor_fluids_open', 'false');
            } else {
                // 当前是悬浮或关闭状态，双击转为嵌入展开
                fluidsContainer.style.display = 'grid';
                fluidsContainer.classList.remove('absolute-panel');
                localStorage.setItem('mvu_monitor_fluids_open', 'true');
            }
            // 触发重绘以更新临时标签的显示状态
            renderUI();
        });

        // 敏感度切换
        $('c-sense-btn').addEventListener('click', () => {
            const charData = _.get(AppState.mvuData, `stat_data.角色.${AppState.activeChar}`, {});
            const current = _.get(charData, '敏感度与境界.当前敏感度等级', '青涩');
            const maxUnlocked = _.get(charData, '敏感度与境界._已解锁最高敏感度', '青涩');

            const maxIdx = SENSE_LEVELS.indexOf(maxUnlocked);
            let curIdx = SENSE_LEVELS.indexOf(current);

            if (maxIdx === -1 || curIdx === -1) return;

            curIdx = (curIdx + 1) > maxIdx ? 0 : curIdx + 1;
            const nextLevel = SENSE_LEVELS[curIdx];

            updateMvu(`stat_data.角色.${AppState.activeChar}.敏感度与境界.当前敏感度等级`, nextLevel, `已切换至: ${nextLevel}`);
        });
    };

    // --- 初始化 ---
    const init = async () => {
        if (typeof waitGlobalInitialized === 'function') {
            await waitGlobalInitialized('Mvu');
        }

        const savedTheme = localStorage.getItem('mvu_monitor_theme');
        if (savedTheme === 'dark') {
            AppState.theme = 'dark';
            $('monitor-app').classList.add('theme-dark');
            const themeIcon = $('toggle-theme')?.querySelector('i');
            if(themeIcon) themeIcon.className = 'fas fa-sun';
        }

        // 读取最小化状态 (默认最小化)
        const savedMin = localStorage.getItem('mvu_monitor_minimized');
        const isMin = savedMin === null ? true : savedMin === 'true';
        if (isMin) {
            $('monitor-app').classList.add('minimized');
            const minIcon = $('toggle-min')?.querySelector('i');
            if(minIcon) minIcon.className = 'fas fa-expand-arrows-alt';
        }

        // 读取装备栏折叠状态 (默认折叠)
        const savedEquipOpen = localStorage.getItem('mvu_monitor_equip_open');
        const equipDetails = $('c-equip-details');
        if (equipDetails) {
            if (savedEquipOpen === 'true') {
                equipDetails.setAttribute('open', '');
            } else {
                equipDetails.removeAttribute('open');
            }
        }

        // 读取配饰栏折叠状态 (默认折叠)
        const savedAccOpen = localStorage.getItem('mvu_monitor_acc_open');
        const accDetails = $('c-acc-details');
        if (accDetails) {
            if (savedAccOpen === 'true') {
                accDetails.setAttribute('open', '');
            } else {
                accDetails.removeAttribute('open');
            }
        }

        // 读取性癖档案折叠状态 (默认折叠)
        const savedFetishOpen = localStorage.getItem('mvu_monitor_fetish_open');
        const fetishDetails = $('c-fetish-details');
        if (fetishDetails) {
            if (savedFetishOpen === 'true') {
                fetishDetails.setAttribute('open', '');
            } else {
                fetishDetails.removeAttribute('open');
            }
        }

        // 读取体液面板折叠状态 (默认折叠)
        const savedFluidsOpen = localStorage.getItem('mvu_monitor_fluids_open');
        const fluidsContainer = $('c-fluids-container');
        if (fluidsContainer && savedFluidsOpen === 'true') {
            fluidsContainer.style.display = 'grid';
            fluidsContainer.classList.remove('absolute-panel');
        }

        if (fetchMvuData()) {
            AppState.isReady = true;
            createParticles();
            bindEvents();
            renderUI();

            if (typeof eventOn === 'function' && typeof Mvu !== 'undefined') {
                eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
                    if(fetchMvuData()) renderUI();
                });
            }
        } else {
            $('monitor-app').innerHTML = '<div style="padding:20px;text-align:center;color:red;">MVU变量系统未就绪或未找到数据，请确保已正确配置并初始化变量。</div>';
        }
    };

    setTimeout(init, 100);

})();
</script>
</body>
</html>
```
